//! Compiled receipt/SAC paths. Genesis and borrowing enablement are TEST ONLY.
use super::*;
use soroban_sdk::{token,testutils::{MockAuth,MockAuthInvoke},xdr::{DiagnosticEvent,LedgerEntry,LedgerEntryData,Limits,ReadXdr}};
const PINNED_PUBLIC_ADMIN:&str="GC4T5MP5ZKILC633IUL6GHWGSIUV6JREN7BKOM6X7XTSVYLNKWZIT7FP";
struct F{e:Env,r:Address,a:Address,u:Address,t:Address,m:Address}
impl F{
 fn actual_fresh_initialize()->Self{
  let mut e=Env::default();e.set_config(soroban_sdk::testutils::EnvTestConfig{capture_snapshot_at_drop:false,..Default::default()});e.ledger().with_mut(|l|{l.sequence_number=100;l.timestamp=1000;l.max_entry_ttl=6_312_000;});cl_resource_limits::configure(&e);
  let a=Address::from_str(&e,PINNED_PUBLIC_ADMIN);let u=Address::generate(&e);let sac=e.register_stellar_asset_contract_v2(a.clone());let t=sac.address();let r=e.register(std::fs::read(format!("{}/receipt_vault.wasm",std::env::var("LENDING_ARCHIVE_WASM_DIR").unwrap())).unwrap().as_slice(),());let m=Address::generate(&e);
  // Public-account/SAC controlled genesis only. This is not a funded network
  // account or a real trustline operation, and supplies no signature authority.
  use soroban_sdk::xdr::*;let ScAddress::Account(account)=(&a).into() else{unreachable!()};let asset=match sac.asset(){Asset::CreditAlphanum4(v)=>TrustLineAsset::CreditAlphanum4(v),Asset::CreditAlphanum12(v)=>TrustLineAsset::CreditAlphanum12(v),_=>panic!("issued test asset required")};
  let mut snapshot=e.to_ledger_snapshot();snapshot.ledger_entries.push((Box::new(LedgerKey::Account(LedgerKeyAccount{account_id:account.clone()})),(Box::new(LedgerEntry{last_modified_ledger_seq:0,data:LedgerEntryData::Account(AccountEntry{account_id:account.clone(),balance:100_000_000,seq_num:SequenceNumber(0),num_sub_entries:1,inflation_dest:None,flags:0,home_domain:Default::default(),thresholds:Thresholds([1,1,1,1]),signers:Default::default(),ext:AccountEntryExt::V0}),ext:LedgerEntryExt::V0}),None)));
  snapshot.ledger_entries.push((Box::new(LedgerKey::Trustline(LedgerKeyTrustLine{account_id:account.clone(),asset:asset.clone()})),(Box::new(LedgerEntry{last_modified_ledger_seq:0,data:LedgerEntryData::Trustline(TrustLineEntry{account_id:account,asset,balance:0,limit:i64::MAX,flags:1,ext:TrustLineEntryExt::V0}),ext:LedgerEntryExt::V0}),None)));
  let identities=[a.to_string().to_string(),u.to_string().to_string(),t.to_string().to_string(),r.to_string().to_string(),m.to_string().to_string()];e=Env::from_ledger_snapshot(snapshot);e.set_config(soroban_sdk::testutils::EnvTestConfig{capture_snapshot_at_drop:false,..Default::default()});cl_resource_limits::configure(&e);let[a,u,t,r,m]=identities.map(|s|Address::from_str(&e,&s));
  resource_profile::register_contracts(&e,&[("fresh-receipt",&r),("SAC",&t)]);let f=Self{e,r,a,u,t,m};let args=(&f.t,0u128,0u128,&f.a).into_val(&f.e);f.auth(&f.a,&f.r,"initialize",args);cl_resource_limits::reset(&f.e);let _:Val=f.e.invoke_contract(&f.r,&Symbol::new(&f.e,"initialize"),(&f.t,0u128,0u128,&f.a).into_val(&f.e));f.meter("actual_fresh_initialize");f
 }
 fn invocation(&self,target:&Address,name:&str,args:Vec<Val>,children:std::vec::Vec<soroban_sdk::xdr::SorobanAuthorizedInvocation>)->soroban_sdk::xdr::SorobanAuthorizedInvocation{use soroban_sdk::xdr::*;SorobanAuthorizedInvocation{function:SorobanAuthorizedFunction::ContractFn(InvokeContractArgs{contract_address:target.into(),function_name:ScSymbol(name.as_bytes().to_vec().try_into().unwrap()),args:args.iter().map(|v|ScVal::try_from_val(&self.e,&v).unwrap()).collect::<std::vec::Vec<_>>().try_into().unwrap()}),sub_invocations:children.try_into().unwrap()}}
 fn source_auth(&self,who:&Address,root:soroban_sdk::xdr::SorobanAuthorizedInvocation){use soroban_sdk::xdr::*;assert_eq!(who.to_string().to_string(),PINNED_PUBLIC_ADMIN);let ScAddress::Account(account)=who.into() else{panic!("source account required")};self.e.host().set_source_account(account).unwrap();self.e.set_auths(&[SorobanAuthorizationEntry{credentials:SorobanCredentials::SourceAccount,root_invocation:root}]);}
 fn new(supply:Option<u128>,borrow:Option<u128>)->Self{
  let mut e=Env::default();e.set_config(soroban_sdk::testutils::EnvTestConfig{capture_snapshot_at_drop:false,..Default::default()});e.ledger().with_mut(|l|{l.sequence_number=100;l.timestamp=1000;l.max_entry_ttl=6_312_000;});cl_resource_limits::configure(&e);
  let a=Address::generate(&e);let u=Address::generate(&e);let t=e.register_stellar_asset_contract_v2(a.clone()).address();
  let r=e.register(std::fs::read(format!("{}/receipt_vault.wasm",std::env::var("LENDING_ARCHIVE_WASM_DIR").unwrap())).unwrap().as_slice(),());
  let m=e.register(std::fs::read(std::env::var("LENDING_CAP_CALLER_WASM").expect("compiled synthetic caller required")).unwrap().as_slice(),());
  for(n,v)in[("Admin",a.clone().into_val(&e)),("UnderlyingToken",t.clone().into_val(&e)),("Initialized",true.into_val(&e)),("RatesReady",true.into_val(&e)),("LastUpdateTime",1000u64.into_val(&e)),("DebtStateVersion",1u32.into_val(&e)),("DebtStateMigratedAt",1000u64.into_val(&e)),("MarginController",m.clone().into_val(&e))]{put(&e,&r,n,v,false)}
  for(n,v)in[("ManagedCash",0u128),("TotalDeposited",0),("YearlyRateScaled",0),("BorrowYearlyRateScaled",0),("AccumulatedInterest",0),("TotalBorrowed",0),("BorrowIndex",1_000_000_000_000_000_000),("CollateralFactorScaled",500_000),("InitialExchangeRate",1_000_000),("ReserveFactorScaled",0),("TotalReserves",0),("AdminFeeScaled",0),("TotalAdminFees",0)]{put(&e,&r,n,v.into_val(&e),false)}
  if let Some(v)=supply{put(&e,&r,"SupplyCap",v.into_val(&e),false)}if let Some(v)=borrow{put(&e,&r,"BorrowCap",v.into_val(&e),false)}
  put(&e,&r,"MinCashReserveBps",0u32.into_val(&e),true);put(&e,&r,"CashBorrowingEnabled",true.into_val(&e),true);
  resource_profile::register_contracts(&e,&[("receipt-supply-cap",&r),("receipt-borrow-cap",&r),("synthetic-cap-caller",&m),("SAC",&t)]);
  let f=Self{e,r,a,u,t,m};f.mint(&f.a,1000);f.mint(&f.u,50_000);if supply.is_some(){f.funded(&f.a,"seed_minimum_supply",1000);}f
 }
 fn malformed_missing_supply_genesis()->Self{
  // Explicit corrupted/absent-state reconstruction, NOT an expiry model.
  let original=Self::new(Some(7000),Some(500));let mut snapshot=original.e.to_ledger_snapshot();let receipt:soroban_sdk::xdr::ScAddress=(&original.r).into();let capval:Val=key(&original.e,"SupplyCap").into_val(&original.e);let cap=soroban_sdk::xdr::ScVal::try_from_val(&original.e,&capval).unwrap();
  snapshot.ledger_entries.retain(|(k,_)|!matches!(k.as_ref(),soroban_sdk::xdr::LedgerKey::ContractData(d) if d.contract==receipt && d.key==cap));
  let mut e=Env::from_ledger_snapshot(snapshot);e.set_config(soroban_sdk::testutils::EnvTestConfig{capture_snapshot_at_drop:false,..Default::default()});cl_resource_limits::configure(&e);
  let convert=|a:&Address|Address::from_str(&e,&a.to_string().to_string());let(r,a,u,t,m)=(convert(&original.r),convert(&original.a),convert(&original.u),convert(&original.t),convert(&original.m));resource_profile::register_contracts(&e,&[("receipt-supply-cap",&r),("receipt-borrow-cap",&r),("synthetic-cap-caller",&m),("SAC",&t)]);Self{e,r,a,u,t,m}
 }
 fn auth(&self,who:&Address,target:&Address,name:&str,args:Vec<Val>){if who.to_string().to_string().starts_with('G'){self.source_auth(who,self.invocation(target,name,args,std::vec![]));}else{self.e.mock_auths(&[MockAuth{address:who,invoke:&MockAuthInvoke{contract:target,fn_name:name,args,sub_invokes:&[]}}]);}}
 fn mint(&self,to:&Address,amount:i128){self.auth(&self.a,&self.t,"mint",(to,amount).into_val(&self.e));token::StellarAssetClient::new(&self.e,&self.t).mint(to,&amount);}
 fn clear_test_margin_binding(&self){let args=(&self.a,Option::<Address>::None).into_val(&self.e);self.auth(&self.a,&self.r,"set_margin_controller",args);let _:Val=self.e.invoke_contract(&self.r,&Symbol::new(&self.e,"set_margin_controller"),(&self.a,Option::<Address>::None).into_val(&self.e));}
 fn funded(&self,who:&Address,name:&str,amount:u128){if who.to_string().to_string().starts_with('G'){let child=self.invocation(&self.t,"transfer",(who,&self.r,amount as i128).into_val(&self.e),std::vec![]);self.source_auth(who,self.invocation(&self.r,name,(who,amount).into_val(&self.e),std::vec![child]));}else{self.e.mock_auths(&[MockAuth{address:who,invoke:&MockAuthInvoke{contract:&self.r,fn_name:name,args:(who,amount).into_val(&self.e),sub_invokes:&[MockAuthInvoke{contract:&self.t,fn_name:"transfer",args:(who,&self.r,amount as i128).into_val(&self.e),sub_invokes:&[]}]}}]);}cl_resource_limits::reset(&self.e);let _:Val=self.e.invoke_contract(&self.r,&Symbol::new(&self.e,name),(who,amount).into_val(&self.e));self.meter(name);}
 fn user_call(&self,name:&str,amount:u128){self.auth(&self.u,&self.r,name,(&self.u,amount).into_val(&self.e));cl_resource_limits::reset(&self.e);let _:Val=self.e.invoke_contract(&self.r,&Symbol::new(&self.e,name),(&self.u,amount).into_val(&self.e));self.meter(name);}
 fn meter(&self,name:&str){let e=&self.e;let r=e.cost_estimate().resources();let mut record=json!({"flow":format!("lending_cap_{name}"),"ok":true,"scope":"compiled receipt/SAC financial root; controlled genesis and narrow external test auth; no V3 or account-signature proof","instructions":r.instructions,"memory_bytes":r.mem_bytes,"read_entries":r.memory_read_entries,"write_entries":r.write_entries,"disk_read_entries":r.disk_read_entries,"read_bytes":r.disk_read_bytes,"write_bytes":r.write_bytes,"contract_events_size_bytes":r.contract_events_size_bytes,"persistent_rent_ledger_bytes":r.persistent_rent_ledger_bytes,"persistent_entry_rent_bumps":r.persistent_entry_rent_bumps,"temporary_rent_ledger_bytes":r.temporary_rent_ledger_bytes,"temporary_entry_rent_bumps":r.temporary_entry_rent_bumps});for(k,v)in cl_resource_limits::metadata().as_object().unwrap(){record[k]=v.clone();}for(k,v)in cl_resource_limits::diagnostics(e).as_object().unwrap(){record[k]=v.clone();}use std::io::Write;let mut file=std::fs::OpenOptions::new().create(true).append(true).open(format!("{}.sdk.jsonl",std::env::var("LENDING_ARCHIVE_REPORT").unwrap())).unwrap();writeln!(file,"{record}").unwrap();}
 fn query<T: soroban_sdk::TryFromVal<Env,Val>>(&self,name:&str,args:Vec<Val>)->T{self.e.invoke_contract(&self.r,&Symbol::new(&self.e,name),args)}
 fn sim(&self,target:&Address,name:&str,args:Vec<Val>,external:Option<&Address>,archive:Option<&str>,expected_error:Option<&str>)->Value{
  let mut row=transaction_evidence::simulate_one(&self.e,target,name,&args,external,external.is_none(),None,archive).unwrap();
  if archive.is_some(){let warm=transaction_evidence::simulate_one(&self.e,target,name,&args,external,external.is_none(),None,None).unwrap();assert_eq!(row["success"],warm["success"]);assert_eq!(row["return_value_xdr"],warm["return_value_xdr"]);assert_eq!(row["post_state_full_data_sha256"],warm["post_state_full_data_sha256"],"cap restoration must preserve the COMPLETE financial poststate");row["archive"]["baseline_full_poststate_sha256"]=warm["post_state_full_data_sha256"].clone();row["archive"]["full_poststate_matches_warm"]=json!(true);}
  {use std::io::Write;let mut file=std::fs::OpenOptions::new().create(true).append(true).open(format!("{}.caps-attempts.jsonl",std::env::var("LENDING_ARCHIVE_REPORT").unwrap())).unwrap();writeln!(file,"{}",json!({"function":name,"archive":archive,"expected_error":expected_error,"evidence":row})).unwrap();}
  assert_eq!(row["success"],expected_error.is_none(),"{row}");assert_eq!(row["limits_pass"],true,"{row}");
  if let Some(message)=expected_error{let events=row["diagnostic_events_xdr"].as_array().unwrap().iter().map(|v|format!("{:?}",DiagnosticEvent::from_xdr_base64(v.as_str().unwrap(),Limits::none()).unwrap())).collect::<std::vec::Vec<_>>().join("\n");assert_eq!(row["error"],"WasmVm(InvalidAction)","semantic rejection {message}: {events}");assert_eq!(row["post_state_unchanged"],true);assert_eq!(row["ledger_changes_empty"],true);}
  if archive.is_some(){let keys=row["archive"]["modified_keys"].as_array().unwrap();assert_eq!(keys.len(),1,"only the exact cap may be expired");assert_eq!(row["archive"]["restoration_observed"],true);if expected_error.is_none(){let key=keys[0]["key_xdr"].as_str().unwrap();let entries=row["entry_size_checks"].as_array().unwrap();let before=entries.iter().find(|v|v["key_xdr"]==key&&v["phase"]=="before").unwrap();let after=entries.iter().find(|v|v["key_xdr"]==key&&v["phase"]=="after").unwrap();let value=|v:&Value|{let entry=LedgerEntry::from_xdr_base64(v["entry_xdr"].as_str().unwrap(),Limits::none()).unwrap();let LedgerEntryData::ContractData(data)=entry.data else{panic!("cap data required")};data.val};assert_eq!(value(before),value(after),"restoration must retain the exact configured cap");}}
  row
 }
}
#[test]
fn compiled_financial_cap_expiry_and_real_absence(){
 let f=F::new(Some(7000),Some(500));f.funded(&f.u,"deposit",5000);assert_eq!(f.query::<u128>("get_ptoken_balance",(&f.u,).into_val(&f.e)),5000);
 let mut rows=std::vec::Vec::new();
 for archive in[None,Some("receipt-supply-cap")]{for(amount,error)in[(1000,None),(1001,Some("supply cap exceeded"))]{rows.push(json!({"label":format!("deposit-cap-{amount}-{archive:?}"),"evidence":f.sim(&f.r,"deposit",(&f.u,amount as u128).into_val(&f.e),Some(&f.u),archive,error)}));}}
 for archive in[None,Some("receipt-borrow-cap")]{for(amount,error)in[(100,None),(501,Some("borrow cap exceeded"))]{rows.push(json!({"label":format!("ordinary-borrow-cap-{amount}-{archive:?}"),"evidence":f.sim(&f.r,"borrow",(&f.u,amount as u128).into_val(&f.e),Some(&f.u),archive,error)}));rows.push(json!({"label":format!("nested-margin-borrow-cap-{amount}-{archive:?}"),"evidence":f.sim(&f.m,"borrow",(&f.r,amount as u128).into_val(&f.e),None,archive,error)}));}}
 // Warm committed financial lifecycle uses actual token transfers and own-contract auth.
 let initial=token::Client::new(&f.e,&f.t).balance(&f.u);f.user_call("borrow",100);assert_eq!(f.query::<u128>("get_user_borrow_balance",(&f.u,).into_val(&f.e)),100);
 for archive in[None,Some("receipt-supply-cap"),Some("receipt-borrow-cap")]{rows.push(json!({"label":format!("repay-with-cap-{archive:?}"),"evidence":f.sim(&f.r,"repay",(&f.u,100u128).into_val(&f.e),Some(&f.u),archive,None)}));}
 f.funded(&f.u,"repay",100);f.clear_test_margin_binding();
 for archive in[None,Some("receipt-supply-cap"),Some("receipt-borrow-cap")]{rows.push(json!({"label":format!("withdraw-with-cap-{archive:?}"),"evidence":f.sim(&f.r,"withdraw",(&f.u,5000u128).into_val(&f.e),Some(&f.u),archive,None)}));}
 f.user_call("withdraw",5000);assert_eq!(token::Client::new(&f.e,&f.t).balance(&f.u),initial+5000);assert_eq!(f.query::<u128>("get_total_borrowed",Vec::new(&f.e)),0);assert_eq!(f.query::<u128>("get_total_ptokens",Vec::new(&f.e)),1000);
 let fresh_missing_supply=F::new(None,Some(500));rows.push(json!({"label":"never-configured-supply-cap-seed-rejects","evidence":fresh_missing_supply.sim(&fresh_missing_supply.r,"seed_minimum_supply",(&fresh_missing_supply.a,1000u128).into_val(&fresh_missing_supply.e),Some(&fresh_missing_supply.a),None,Some("supply cap missing"))}));
 let missing_supply=F::malformed_missing_supply_genesis();rows.push(json!({"label":"malformed-missing-supply-cap-deposit-rejects-not-expiry","evidence":missing_supply.sim(&missing_supply.r,"deposit",(&missing_supply.u,1u128).into_val(&missing_supply.e),Some(&missing_supply.u),None,Some("supply cap missing"))}));
 let missing_borrow=F::new(Some(7000),None);missing_borrow.funded(&missing_borrow.u,"deposit",5000);
 rows.push(json!({"label":"never-configured-borrow-cap-ordinary-rejects","evidence":missing_borrow.sim(&missing_borrow.r,"borrow",(&missing_borrow.u,1u128).into_val(&missing_borrow.e),Some(&missing_borrow.u),None,Some("borrow cap missing"))}));
 rows.push(json!({"label":"never-configured-borrow-cap-margin-rejects","evidence":missing_borrow.sim(&missing_borrow.m,"borrow",(&missing_borrow.r,1u128).into_val(&missing_borrow.e),None,None,Some("borrow cap missing"))}));
 // Missing borrow cap does not disable an existing debt-free holder's exit.
 missing_borrow.clear_test_margin_binding();missing_borrow.user_call("withdraw",5000);assert_eq!(missing_borrow.query::<u128>("get_total_ptokens",Vec::new(&missing_borrow.e)),1000);
 let report=json!({"scope":"compiled receipt/SAC plus compiled synthetic margin caller; controlled genesis, TEST-ONLY enabled borrowing; no V3/controller-health/signature/Core/live-state claim","warm_committed_roundtrip":{"deposit":5000,"borrow":100,"repay":100,"withdraw":5000,"remaining_locked_seed":1000,"debt":0},"missing_borrow_cap_withdraw_succeeds":true,"rows":rows});std::fs::write(format!("{}.caps.json",std::env::var("LENDING_ARCHIVE_REPORT").unwrap()),serde_json::to_vec_pretty(&report).unwrap()).unwrap();
}

#[test]
fn compiled_actual_fresh_initialize_seed_lifecycle_and_unsupported_upgrade(){
 let f=F::actual_fresh_initialize();let e=&f.e;
 assert_eq!(f.query::<Option<u32>>("get_min_cash_reserve_bps",Vec::new(e)),Some(0));assert!(!f.query::<bool>("get_cash_borrowing_enabled",Vec::new(e)));assert_eq!(f.query::<u128>("get_minimum_supply",Vec::new(e)),0);assert_eq!(f.query::<Option<Address>>("get_margin_controller",Vec::new(e)),None);
 e.as_contract(&f.r,||{assert_eq!(e.storage().persistent().get::<_,u128>(&key(e,"SupplyCap")),Some(0));assert_eq!(e.storage().persistent().get::<_,u128>(&key(e,"BorrowCap")),Some(0));assert_eq!(e.storage().persistent().get::<_,bool>(&key(e,"RatesReady")),Some(false));assert!(!e.storage().persistent().has(&key(e,"Peridottroller")));assert!(!e.storage().persistent().has(&key(e,"InterestModel")));assert!(!e.storage().persistent().has(&key(e,"BoostedVault")));});
 f.mint(&f.a,1000);f.mint(&f.u,1241);let mut rows=std::vec::Vec::new();
 rows.push(json!({"label":"fresh-seed-before-deposit","evidence":f.sim(&f.r,"seed_minimum_supply",(&f.a,1000u128).into_val(e),Some(&f.a),None,None)}));f.funded(&f.a,"seed_minimum_supply",1000);
 rows.push(json!({"label":"fresh-first-deposit","evidence":f.sim(&f.r,"deposit",(&f.u,1234u128).into_val(e),Some(&f.u),None,None)}));f.funded(&f.u,"deposit",1234);
 assert_eq!(f.query::<u128>("get_ptoken_balance",(&f.u,).into_val(e)),1234);
 rows.push(json!({"label":"fresh-full-holder-withdrawal","evidence":f.sim(&f.r,"withdraw",(&f.u,1234u128).into_val(e),Some(&f.u),None,None)}));f.user_call("withdraw",1234);assert_eq!(token::Client::new(e,&f.t).balance(&f.u),1241);assert_eq!(f.query::<u128>("get_total_ptokens",Vec::new(e)),1000);
 rows.push(json!({"label":"fresh-next-deposit-after-last-holder-exit","evidence":f.sim(&f.r,"deposit",(&f.u,7u128).into_val(e),Some(&f.u),None,None)}));f.funded(&f.u,"deposit",7);assert_eq!(f.query::<u128>("get_ptoken_balance",(&f.u,).into_val(e)),7);assert_eq!(f.query::<u128>("get_total_ptokens",Vec::new(e)),1007);assert_eq!(f.query::<u128>("get_total_underlying",Vec::new(e)),1007);assert_eq!(f.query::<u128>("get_minimum_supply",Vec::new(e)),1000);assert!(!f.query::<bool>("get_cash_borrowing_enabled",Vec::new(e)));
 rows.push(json!({"label":"fresh-reinitialize-rejected","evidence":f.sim(&f.r,"initialize",(&f.t,0u128,0u128,&f.a).into_val(e),Some(&f.a),None,Some("already initialized"))}));
 // Explicit unsupported legacy-state counterexample. No actual upgrade or TTL
 // expiration is claimed: retain nonzero economic state but omit its new floor.
 let mut legacy=Env::from_ledger_snapshot(e.to_ledger_snapshot());legacy.set_config(soroban_sdk::testutils::EnvTestConfig{capture_snapshot_at_drop:false,..Default::default()});cl_resource_limits::configure(&legacy);let convert=|a:&Address|Address::from_str(&legacy,&a.to_string().to_string());let(r,a,u,t,m)=(convert(&f.r),convert(&f.a),convert(&f.u),convert(&f.t),convert(&f.m));legacy.as_contract(&r,||legacy.storage().instance().remove(&key(&legacy,"PermanentMinimumSupply")));let unsupported=F{e:legacy,r,a,u,t,m};let l=&unsupported.e;
 assert_eq!(unsupported.query::<u128>("get_total_ptokens",Vec::new(l)),1007);assert_eq!(unsupported.query::<u128>("get_minimum_supply",Vec::new(l)),0);
 rows.push(json!({"label":"unsupported-nonempty-unseeded-deposit-rejects","evidence":unsupported.sim(&unsupported.r,"deposit",(&unsupported.u,1u128).into_val(l),Some(&unsupported.u),None,Some("cash market must be explicitly seeded"))}));
 rows.push(json!({"label":"unsupported-nonempty-unseeded-seeding-rejects","evidence":unsupported.sim(&unsupported.r,"seed_minimum_supply",(&unsupported.a,1000u128).into_val(l),Some(&unsupported.a),None,Some("minimum supply requires empty market"))}));
 std::fs::write(format!("{}.fresh.json",std::env::var("LENDING_ARCHIVE_REPORT").unwrap()),serde_json::to_vec_pretty(&json!({"scope":"actual compiled initialize and contiguous SDK fresh lifecycle; exact public admin with scoped SourceAccount host auth; no G-address mock registration, no signing or Core signature proof; unsupported legacy state is synthetic, not an executed upgrade","initialized_via_production_entrypoint":true,"borrowing_enabled":false,"seed":1000,"first_deposit":1234,"holder_withdrawal":1234,"next_deposit":7,"final_supply":1007,"rows":rows})).unwrap()).unwrap();
}
